<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>每日视界 - 专注于为您提供权威、全面的新闻资讯</title>
    <style>
        :root {
            --primary: #c00;
            --dark: #222;
            --gray: #666;
            --light: #f4f4f4;
            --white: #fff;
            --border: #e0e0e0;
            --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans SC", sans-serif;
            --font-serif: "Georgia", "Times New Roman", "Noto Serif SC", serif;
        }

        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            font-family: var(--font-main);
            color: var(--dark);
            line-height: 1.6;
            background-color: var(--light);
        }

        a { text-decoration: none; color: inherit; transition: color 0.2s; }
        a:hover { color: var(--primary); }
        ul { list-style: none; }

        /* Utility */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }
        .btn {
            display: inline-block;
            padding: 8px 16px;
            background: var(--dark);
            color: var(--white);
            border-radius: 4px;
            font-size: 0.9rem;
        }
        .btn:hover { opacity: 0.9; }
        .tag {
            font-size: 0.8rem;
            font-weight: bold;
            color: var(--primary);
            margin-right: 5px;
        }

        /* Header */
        .top-bar {
            background: #000;
            color: #aaa;
            font-size: 0.85rem;
            padding: 5px 0;
        }
        .top-bar .container { display: flex; justify-content: space-between; }

        header {
            background: var(--white);
            border-bottom: 3px solid var(--primary);
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .header-main {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px 0;
        }

        .logo {
            font-size: 2rem;
            font-weight: 800;
            font-family: var(--font-serif);
            letter-spacing: -1px;
            color: var(--dark);
        }
        .logo span { color: var(--primary); }

        .search-bar {
            display: none;
        }

        nav ul {
            display: flex;
            gap: 25px;
        }
        nav a {
            font-weight: 500;
            font-size: 1rem;
            position: relative;
        }
        nav a::after {
            content: '';
            position: absolute;
            bottom: -5px;
            left: 0;
            width: 0;
            height: 2px;
            background: var(--primary);
            transition: width 0.3s;
        }
        nav a:hover::after { width: 100%; }

        /* Layout */
        .hero-section {
            display: grid;
            grid-template-columns: 2fr 1fr;
            gap: 20px;
            margin: 20px auto;
            padding: 0 20px;
        }

        .hero-card {
            position: relative;
            background: #ddd;
            color: white;
            border-radius: 8px;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            justify-content: flex-end;
            height: 400px;
        }

        .hero-card.bg-tech { background: #2c3e50; }
        .hero-card.bg-econ { background: #34495e; }
        .hero-card.bg-sport { background: #1a252f; }

        .hero-overlay {
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background: linear-gradient(to top, rgba(0,0,0,0.9), transparent);
            padding: 30px;
        }

        .hero-title {
            font-size: 2.5rem;
            font-family: var(--font-serif);
            margin-bottom: 10px;
            line-height: 1.2;
        }

        .side-list {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .side-item {
            display: flex;
            gap: 15px;
            align-items: center;
            background: var(--white);
            padding: 15px;
            border: 1px solid var(--border);
            border-radius: 6px;
        }

        .side-number {
            font-size: 1.5rem;
            font-weight: 800;
            color: #ddd;
            font-family: var(--font-serif);
        }

        .main-content {
            display: grid;
            grid-template-columns: 2fr 1fr;
            gap: 30px;
            margin-bottom: 50px;
        }

        .section-title {
            font-size: 1.2rem;
            font-weight: 700;
            border-left: 5px solid var(--primary);
            padding-left: 10px;
            margin-bottom: 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .news-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 20px;
        }

        .news-card {
            background: var(--white);
            border-radius: 6px;
            overflow: hidden;
            border: 1px solid var(--border);
            transition: transform 0.2s;
        }

        .news-card:hover { transform: translateY(-3px); box-shadow: 0 5px 15px rgba(0,0,0,0.1); }

        .news-content { padding: 15px; }

        .news-title {
            font-size: 1.1rem;
            font-weight: 700;
            margin-bottom: 8px;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }

        .news-summary {
            font-size: 0.9rem;
            color: var(--gray);
            margin-bottom: 10px;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }

        .meta-info {
            font-size: 0.8rem;
            color: #888;
            display: flex;
            justify-content: space-between;
        }

        .sidebar-ad {
            background: #e9e9e9;
            height: 250px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #999;
            margin-bottom: 20px;
            border-radius: 6px;
        }

        .trending-list li {
            padding: 10px 0;
            border-bottom: 1px solid #eee;
        }
        .trending-list li:last-child { border-bottom: none; }
        .trending-list a {
            font-size: 1rem;
            display: block;
        }
        .trending-list .rank {
            color: var(--gray);
            font-size: 0.9rem;
            margin-right: 5px;
        }

        footer {
            background: #111;
            color: #888;
            padding: 40px 0;
            margin-top: 50px;
            font-size: 0.9rem;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 20px;
            margin-bottom: 30px;
        }

        .footer-col h4 {
            color: var(--white);
            margin-bottom: 15px;
        }

        .footer-col ul li { margin-bottom: 8px; }
        .footer-col a:hover { color: var(--white); }

        .copyright {
            text-align: center;
            padding-top: 20px;
            border-top: 1px solid #333;
        }

        /* Responsive */
        @media (max-width: 768px) {
            .nav-desktop { display: none; }
            .hero-section { grid-template-columns: 1fr; }
            .hero-card { height: 300px; }
            .news-grid { grid-template-columns: 1fr; }
            .main-content { grid-template-columns: 1fr; }
            .footer-grid { grid-template-columns: 1fr 1fr; }
        }
    </style>
</head>
